// Build the Claude Messages request exactly like eval/request.py
// (docs/contracts.md "Claude request shape" + Amendment 1). Keep the two in sync.
const start = $('Start').first().json;
const TOOL_DESCRIPTION = 'Record the qualified lead extracted from the call transcript.';
const MAX_TOKENS = 1024;
const PROFILE_KEYS = ['temperature', 'thinking']; // merge order after max_tokens

// Load Prompt emits one binary item per file; index them by file name.
const files = {};
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) continue;
  const name = String(bin.fileName || items[i].json.fileName || '').split('/').pop();
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  files[name] = buf.toString('utf8');
}
for (const f of ['system.md', 'schema.json', 'meta.json', 'model_params.json']) {
  if (typeof files[f] !== 'string') {
    throw new Error(`Prompt file missing: ${f} (prompt_dir=${start.prompt_dir})`);
  }
}

const meta = JSON.parse(files['meta.json']);
const schema = JSON.parse(files['schema.json']);
const modelParams = JSON.parse(files['model_params.json']);
if (!meta.version || !meta.tool_name) {
  throw new Error('meta.json must contain "version" and "tool_name"');
}

// input_schema = schema.json minus the top-level "$schema" and "$id" keys.
const inputSchema = {};
for (const [k, v] of Object.entries(schema)) {
  if (k !== '$schema' && k !== '$id') inputSchema[k] = v;
}

// Per-model profile; unknown model -> no extra keys.
const profile = modelParams[start.model] || {};
const request = { model: start.model, max_tokens: MAX_TOKENS };
for (const k of PROFILE_KEYS) {
  if (Object.prototype.hasOwnProperty.call(profile, k)) request[k] = JSON.parse(JSON.stringify(profile[k]));
}
request.system = files['system.md'];
request.tools = [{ name: meta.tool_name, description: TOOL_DESCRIPTION, input_schema: inputSchema }];
request.tool_choice = { type: 'tool', name: meta.tool_name };
request.messages = [
  { role: 'user', content: '<transcript>\n' + String(start.transcript_text ?? '') + '\n</transcript>' },
];

return [{
  json: {
    conversation_id: start.conversation_id,
    prompt_dir: start.prompt_dir,
    model: start.model,
    prompt_version: meta.version,
    tool_name: meta.tool_name,
    input_schema: inputSchema,
    request,
    attempt: 1,
    started_at: Date.now(),
  },
}];

// Validate the tool_use input against the prompt's JSON Schema (2020-12) and
// record latency + token usage. Runs once per attempt: run 0 = attempt 1,
// run 1 = the single retry. Validator: @cfworker/json-schema (contracts.md
// Amendment 3: n8n 2.x runners forbid the code generation Ajv needs). Errors
// are normalised to eval/validate.py's Ajv-style {path, message}, sorted.
const { Validator } = require('@cfworker/json-schema');

const attempt = $runIndex + 1;
const ctx = attempt === 1 ? $('Build Request').first().json : $('Build Retry').first().json;
const res = $input.first().json || {};
const latency_ms = Math.max(0, Date.now() - Number(ctx.started_at || Date.now()));

function describeError(e) {
  if (e === null || e === undefined) return 'unknown error';
  if (typeof e !== 'object') return String(e);
  const status = e.httpCode || e.statusCode || e.status || (e.response && e.response.status) || '';
  const parts = [];
  if (status && !String(e.message || '').startsWith(String(status))) parts.push(String(status));
  if (e.message) parts.push(String(e.message));
  let body = (e.cause && e.cause.message) || e.description || e.error || (e.response && e.response.data) || '';
  if (body && typeof body !== 'string') body = JSON.stringify(body);
  if (body && body !== e.message) parts.push(String(body));
  return (parts.join(' - ') || JSON.stringify(e)).slice(0, 900);
}

// JSON pointer helpers for cfworker's "#/a/b" locations.
const tokens = (loc) => String(loc || '#').replace(/^#\/?/, '').split('/').filter((t) => t !== '')
  .map((t) => decodeURIComponent(t).replace(/~1/g, '/').replace(/~0/g, '~'));
const toPath = (loc) => tokens(loc).map((t) => '/' + t.replace(/~/g, '~0').replace(/\//g, '~1')).join('');
const resolve = (root, loc) => tokens(loc).reduce((node, t) => (node == null ? undefined : node[t]), root);

// Leaf keywords -> Ajv default wording (as mirrored by eval/validate.py).
// Wrapper errors (properties, items, allOf, ...) and cfworker's "false"
// boolean-schema echoes are dropped.
function normalise(schema, errors) {
  const out = [];
  for (const e of errors) {
    const kw = e.keyword;
    const path = toPath(e.instanceLocation);
    const val = resolve(schema, e.keywordLocation);
    const quoted = (String(e.error).match(/"([^"]*)"/) || [])[1];
    if (kw === 'type') out.push({ path, message: 'must be ' + (Array.isArray(val) ? val.join(',') : val) });
    else if (kw === 'enum') out.push({ path, message: 'must be equal to one of the allowed values' });
    else if (kw === 'const') out.push({ path, message: 'must be equal to constant' });
    else if (kw === 'minimum') out.push({ path, message: 'must be >= ' + val });
    else if (kw === 'maximum') out.push({ path, message: 'must be <= ' + val });
    else if (kw === 'minLength') out.push({ path, message: `must NOT have fewer than ${val} characters` });
    else if (kw === 'maxLength') out.push({ path, message: `must NOT have more than ${val} characters` });
    else if (kw === 'required') out.push({ path, message: `must have required property '${quoted}'` });
    else if (kw === 'additionalProperties') {
      // cfworker (shortCircuit=false) also reports declared properties that
      // failed their own subschema as "additional"; keep only real extras.
      const parent = resolve(schema, String(e.keywordLocation).replace(/\/additionalProperties$/, '')) || {};
      const declared = parent.properties && Object.prototype.hasOwnProperty.call(parent.properties, quoted);
      if (!declared) out.push({ path, message: 'must NOT have additional properties' });
    } else if (['properties', 'items', 'prefixItems', 'allOf', 'anyOf', 'oneOf', 'not', 'if', 'then', 'else',
      '$ref', 'false', 'unevaluatedProperties', 'dependentSchemas', 'contains'].includes(kw)) {
      continue;
    } else {
      out.push({ path, message: String(e.error) });
    }
  }
  return out;
}

const usage = res.usage || {};
let is_valid = false;
let output = null;
let validation_errors = null;
let api_error = null;
let tool_use_id = null;
let response_content = null;

if (res.error !== undefined && res.content === undefined) {
  // Claude call failed after the HTTP node's retries (429/5xx/timeout/4xx).
  api_error = 'Claude API error: ' + describeError(res.error);
  validation_errors = [{ path: '', message: api_error }];
} else {
  response_content = Array.isArray(res.content) ? res.content : [];
  const block = response_content.find((b) => b && b.type === 'tool_use' && b.name === ctx.tool_name);
  if (!block || res.stop_reason === 'max_tokens') {
    // Amendment 1: truncated or missing tool call = invalid output (retried once).
    const reason = res.stop_reason === null || res.stop_reason === undefined ? 'None' : res.stop_reason;
    validation_errors = [{ path: '/', message: `no complete tool_use block (stop_reason=${reason})` }];
    output = block && block.input !== undefined ? block.input : null;
  } else {
    output = block.input === undefined ? null : block.input;
    const result = new Validator(ctx.input_schema, '2020-12', false).validate(output);
    if (!result.valid) {
      validation_errors = normalise(ctx.input_schema, result.errors);
      if (!validation_errors.length) validation_errors = [{ path: '', message: 'does not match schema' }];
    }
  }
  if (block) tool_use_id = block.id;
  is_valid = validation_errors === null;
}

if (validation_errors) {
  validation_errors.sort((a, b) =>
    a.path < b.path ? -1 : a.path > b.path ? 1 : a.message < b.message ? -1 : a.message > b.message ? 1 : 0);
}

return [{
  json: {
    conversation_id: ctx.conversation_id,
    attempt,
    prompt_version: ctx.prompt_version,
    model: ctx.model,
    tool_name: ctx.tool_name,
    is_valid,
    output,
    validation_errors,
    latency_ms,
    input_tokens: Number.isInteger(usage.input_tokens) ? usage.input_tokens : null,
    output_tokens: Number.isInteger(usage.output_tokens) ? usage.output_tokens : null,
    stop_reason: res.stop_reason === undefined ? null : res.stop_reason,
    api_error,
    // One retry, only for bad output (never for API errors).
    retryable: !is_valid && !api_error && attempt === 1,
    tool_use_id,
    response_content,
  },
}];

// Attempt-2 request, identical to eval/request.py build_retry_request():
// attempt-1 request + assistant turn (the original response content) + a user
// tool_result with is_error=true listing the validation errors. If attempt 1
// had no tool_use block there is nothing to answer, so attempt 1 is re-sent
// unchanged (contracts.md Amendment 1).
const base = $('Build Request').first().json;
const v = $('Validate').first().json;

const request = JSON.parse(JSON.stringify(base.request));
if (v.tool_use_id) {
  const lines = (v.validation_errors || []).map((e) => `- ${e.path || '/'}: ${e.message}`);
  request.messages.push({ role: 'assistant', content: v.response_content });
  request.messages.push({
    role: 'user',
    content: [{
      type: 'tool_result',
      tool_use_id: v.tool_use_id,
      is_error: true,
      content: 'Schema validation failed:\n' + lines.join('\n'),
    }],
  });
}

return [{ json: { ...base, request, attempt: 2, started_at: Date.now() } }];
